class Solution:
    def findUnclaimed(self, tickets: List[int]) -> List[int]:
        return [x for x in range(1, len(tickets) + 1) if x not in tickets]

code.java:
class Solution {
    public int[] findUnclaimed(int[] tickets) {
        int n = tickets.length;
        List<Integer> out = new ArrayList<>();
        for (int x = 1; x <= n; x++) {
            boolean found = false;
            for (int v : tickets) if (v == x) { found = true; break; }
            if (!found) out.add(x);
        }
        return out.stream().mapToInt(Integer::intValue).toArray();
    }
}

