class Solution:
    def findUnclaimed(self, tickets: List[int]) -> List[int]:
        n = len(tickets)
        seen = [False] * (n + 1)
        for v in tickets:
            seen[v] = True
        return [x for x in range(1, n + 1) if not seen[x]]

