    int n = ticketsSize;
    bool* seen = calloc(n + 1, sizeof(bool));
    for (int i = 0; i < n; i++) seen[tickets[i]] = true;
    int* out = malloc(n * sizeof(int));
    *returnSize = 0;
    for (int x = 1; x <= n; x++) if (!seen[x]) out[(*returnSize)++] = x;
