class Solution:
    def findUnclaimed(self, tickets: List[int]) -> List[int]:
        for x in tickets:
            v = abs(x)
            tickets[v - 1] = -abs(tickets[v - 1])
        out = [i + 1 for i, x in enumerate(tickets) if x > 0]
        for i in range(len(tickets)):
            tickets[i] = abs(tickets[i])
        return out

