class Solution {
    public int[] findUnclaimed(int[] tickets) {
        for (int x : tickets) {
            int v = Math.abs(x);
            tickets[v - 1] = -Math.abs(tickets[v - 1]);
        }
        List<Integer> out = new ArrayList<>();
        for (int i = 0; i < tickets.length; i++) if (tickets[i] > 0) out.add(i + 1);
        for (int i = 0; i < tickets.length; i++) tickets[i] = Math.abs(tickets[i]);
        return out.stream().mapToInt(Integer::intValue).toArray();
    }
}

